          "id": "code-ml-18-1-ch18_1_diag",
          "title": "Production Diversity Audit: Matriks Kuncheva Q/D/DF & Jebakan Accuracy-Diversity Trade-Off",
          "language": "python",
          "filename": "18_1_diversity_audit_weak_model_trap.py",
          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import ExtraTreesClassifier, HistGradientBoostingClassifier\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import accuracy_score, log_loss, roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import StandardScaler\nfrom sklearn.tree import DecisionTreeClassifier\n\nX, y = make_classification(\n    n_samples=1200, n_features=14, n_informative=8, n_redundant=3,\n    class_sep=0.95, flip_y=0.05, random_state=42\n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.30, stratify=y, random_state=42)\n\nmodels = {\n    \"LogReg\": Pipeline([(\"sc\", StandardScaler()), (\"m\", LogisticRegression(C=0.8, random_state=42))]),\n    \"MLP\": Pipeline([(\"sc\", StandardScaler()), (\"m\", MLPClassifier(hidden_layer_sizes=(24, 12), solver=\"lbfgs\", alpha=0.2, max_iter=150, random_state=42))]),\n    \"ExtraTrees\": ExtraTreesClassifier(n_estimators=45, min_samples_leaf=3, random_state=42),\n    \"HistGBDT\": HistGradientBoostingClassifier(max_iter=45, max_depth=4, max_bins=64, early_stopping=False, random_state=42),\n}\n\nprobs = {}\ncorrect = {}\nprint(\"=== 1. Skor Model Tunggal (Test Set N=360) ===\")\nfor name, mdl in models.items():\n    mdl.fit(X_tr, y_tr)\n    p = mdl.predict_proba(X_te)[:, 1]\n    probs[name] = p\n    correct[name] = ((p >= 0.5).astype(int) == y_te).astype(int)\n    print(f\"  {name:12s} | Acc={accuracy_score(y_te, p >= 0.5):.4f} | AUROC={roc_auc_score(y_te, p):.4f} | LogLoss={log_loss(y_te, p):.4f}\")\n\n# Model lemah bising sejati (dilatih HANYA di X_tr pada 2 fitur lemah -> akurasi rendah, Yule Q rendah!)\nweak_clf = DecisionTreeClassifier(max_depth=1, random_state=42).fit(X_tr[:, -2:], y_tr)\np_noisy = weak_clf.predict_proba(X_te[:, -2:])[:, 1]\nprobs[\"WeakNoisy\"] = p_noisy\ncorrect[\"WeakNoisy\"] = ((p_noisy >= 0.5).astype(int) == y_te).astype(int)\nprint(f\"  {'WeakNoisy':12s} | Acc={accuracy_score(y_te, p_noisy >= 0.5):.4f} | AUROC={roc_auc_score(y_te, p_noisy):.4f} | LogLoss={log_loss(y_te, p_noisy):.4f}\")\n\ndef pairwise_q_d_df(c1: np.ndarray, c2: np.ndarray) -> tuple[float, float, float]:\n    n11 = float(np.sum((c1 == 1) & (c2 == 1)))\n    n10 = float(np.sum((c1 == 1) & (c2 == 0)))\n    n01 = float(np.sum((c1 == 0) & (c2 == 1)))\n    n00 = float(np.sum((c1 == 0) & (c2 == 0)))\n    q = (n11 * n00 - n01 * n10) / max(n11 * n00 + n01 * n10, 1e-12)\n    return q, (n10 + n01) / len(c1), n00 / len(c1)\n\nprint(\"\\n=== 2. Audit Matriks Diversitas Pasangan terhadap HistGBDT ===\")\nfor name in [\"ExtraTrees\", \"MLP\", \"LogReg\", \"WeakNoisy\"]:\n    q, d, df = pairwise_q_d_df(correct[\"HistGBDT\"], correct[name])\n    print(f\"  HistGBDT vs {name:10s} | Yule Q={q:+.4f} | Disagreement D={d:.4f} | Double-Fault DF={df:.4f}\")\n\nprint(\"\\n=== 3. Jebakan Accuracy-Diversity Trade-Off (Menambah Model Lemah Ber-Q Rendah) ===\")\nsubsets = [\n    (\"HistGBDT + ExtraTrees (Tree-only)\", [\"HistGBDT\", \"ExtraTrees\"]),\n    (\"HistGBDT + MLP + LogReg (3 Keluarga Kuat)\", [\"HistGBDT\", \"MLP\", \"LogReg\"]),\n    (\"4 Keluarga Kuat (Semua)\", [\"HistGBDT\", \"ExtraTrees\", \"MLP\", \"LogReg\"]),\n    (\"4 Kuat + WeakNoisy (Jebakan Q Rendah!)\", [\"HistGBDT\", \"ExtraTrees\", \"MLP\", \"LogReg\", \"WeakNoisy\"]),\n]\nfor label, keys in subsets:\n    p_ens = np.mean([probs[k] for k in keys], axis=0)\n    print(f\"  {label:42s} | AUROC={roc_auc_score(y_te, p_ens):.4f} | LogLoss={log_loss(y_te, p_ens):.4f}\")",
          "expectedOutput": "=== 1. Skor Model Tunggal (Test Set N=360) ===\n  LogReg       | Acc=0.7250 | AUROC=0.8073 | LogLoss=0.5144\n  MLP          | Acc=0.8861 | AUROC=0.9380 | LogLoss=0.8921\n  ExtraTrees   | Acc=0.8694 | AUROC=0.9347 | LogLoss=0.4338\n  HistGBDT     | Acc=0.8639 | AUROC=0.9257 | LogLoss=0.3690\n  WeakNoisy    | Acc=0.6000 | AUROC=0.6000 | LogLoss=0.6697\n\n=== 2. Audit Matriks Diversitas Pasangan terhadap HistGBDT ===\n  HistGBDT vs ExtraTrees | Yule Q=+0.9293 | Disagreement D=0.1000 | Double-Fault DF=0.0833\n  HistGBDT vs MLP        | Yule Q=+0.9142 | Disagreement D=0.1056 | Double-Fault DF=0.0722\n  HistGBDT vs LogReg     | Yule Q=+0.7690 | Disagreement D=0.2278 | Double-Fault DF=0.0917\n  HistGBDT vs WeakNoisy  | Yule Q=+0.5022 | Disagreement D=0.3639 | Double-Fault DF=0.0861\n\n=== 3. Jebakan Accuracy-Diversity Trade-Off (Menambah Model Lemah Ber-Q Rendah) ===\n  HistGBDT + ExtraTrees (Tree-only)          | AUROC=0.9350 | LogLoss=0.3918\n  HistGBDT + MLP + LogReg (3 Keluarga Kuat)  | AUROC=0.9351 | LogLoss=0.3390\n  4 Keluarga Kuat (Semua)                    | AUROC=0.9399 | LogLoss=0.3559\n  4 Kuat + WeakNoisy (Jebakan Q Rendah!)     | AUROC=0.9400 | LogLoss=0.4002",
          "actualOutput": "=== 1. Skor Model Tunggal (Test Set N=360) ===\n  LogReg       | Acc=0.7250 | AUROC=0.8073 | LogLoss=0.5144\n  MLP          | Acc=0.8861 | AUROC=0.9380 | LogLoss=0.8921\n  ExtraTrees   | Acc=0.8694 | AUROC=0.9347 | LogLoss=0.4338\n  HistGBDT     | Acc=0.8639 | AUROC=0.9257 | LogLoss=0.3690\n  WeakNoisy    | Acc=0.6000 | AUROC=0.6000 | LogLoss=0.6697\n\n=== 2. Audit Matriks Diversitas Pasangan terhadap HistGBDT ===\n  HistGBDT vs ExtraTrees | Yule Q=+0.9293 | Disagreement D=0.1000 | Double-Fault DF=0.0833\n  HistGBDT vs MLP        | Yule Q=+0.9142 | Disagreement D=0.1056 | Double-Fault DF=0.0722\n  HistGBDT vs LogReg     | Yule Q=+0.7690 | Disagreement D=0.2278 | Double-Fault DF=0.0917\n  HistGBDT vs WeakNoisy  | Yule Q=+0.5022 | Disagreement D=0.3639 | Double-Fault DF=0.0861\n\n=== 3. Jebakan Accuracy-Diversity Trade-Off (Menambah Model Lemah Ber-Q Rendah) ===\n  HistGBDT + ExtraTrees (Tree-only)          | AUROC=0.9350 | LogLoss=0.3918\n  HistGBDT + MLP + LogReg (3 Keluarga Kuat)  | AUROC=0.9351 | LogLoss=0.3390\n  4 Keluarga Kuat (Semua)                    | AUROC=0.9399 | LogLoss=0.3559\n  4 Kuat + WeakNoisy (Jebakan Q Rendah!)     | AUROC=0.9400 | LogLoss=0.4002",
