          "code": "import numpy as np\nfrom sklearn.ensemble import GradientBoostingRegressor\nfrom sklearn.linear_model import Ridge\nfrom sklearn.metrics import root_mean_squared_error\nfrom sklearn.model_selection import KFold, train_test_split\nfrom sklearn.tree import DecisionTreeRegressor\n\nrng = np.random.default_rng(1820)\nN = 800\nX = rng.normal(0.0, 1.0, size=(N, 8))\ny = (\n    2.5 * X[:, 0]\n    - 1.8 * X[:, 1]\n    + 1.6 * np.sin(1.3 * X[:, 2])\n    + 1.2 * X[:, 3] * X[:, 4]\n    + rng.normal(0.0, 1.35, size=N)\n)\nX_tr, X_te, y_tr, y_te = train_test_split(X, y, test_size=0.30, random_state=42)\n\ndef build_base_learners():\n    return [\n        (\"Ridge\", Ridge(alpha=3.0)),\n        (\"GBDT\", GradientBoostingRegressor(n_estimators=45, max_depth=3, learning_rate=0.08, random_state=42)),\n        (\"OverfitTree\", DecisionTreeRegressor(max_depth=None, min_samples_leaf=1, random_state=42)),\n    ]\n\n# 1) ANTI-PATTERN: In-Sample Stacking (Meta-learner dilatih di atas prediksi latih -> BOCOR!)\nZ_in_tr = np.zeros((len(X_tr), 3))\nZ_in_te = np.zeros((len(X_te), 3))\nfor j, (name, mdl) in enumerate(build_base_learners()):\n    mdl.fit(X_tr, y_tr)\n    Z_in_tr[:, j] = mdl.predict(X_tr)\n    Z_in_te[:, j] = mdl.predict(X_te)\n\nmeta_leaky = Ridge(alpha=0.1).fit(Z_in_tr, y_tr)\npred_leaky = meta_leaky.predict(Z_in_te)\n\n# 2) PRODUCTION-SAFE: Strict 5-Fold Out-of-Fold (OOF) Matrix Construction dari Nol\nkf = KFold(n_splits=5, shuffle=True, random_state=42)\nZ_oof = np.zeros((len(X_tr), 3))\nfor tr_idx, val_idx in kf.split(X_tr):\n    for j, (_, mdl) in enumerate(build_base_learners()):\n        mdl.fit(X_tr[tr_idx], y_tr[tr_idx])\n        Z_oof[val_idx, j] = mdl.predict(X_tr[val_idx])\n\nmeta_oof = Ridge(alpha=1.0).fit(Z_oof, y_tr)\n# Base learners di-refit pada 100% X_tr untuk menghasilkan Z_te (sama dengan Z_in_te)\npred_oof = meta_oof.predict(Z_in_te)\n\nprint(\"=== Performa Base Learners Tunggal (Train vs Test RMSE) ===\")\nfor j, (name, _) in enumerate(build_base_learners()):\n    r_tr = root_mean_squared_error(y_tr, Z_in_tr[:, j])\n    r_oof = root_mean_squared_error(y_tr, Z_oof[:, j])\n    r_te = root_mean_squared_error(y_te, Z_in_te[:, j])\n    print(f\"  {name:12s} | In-Sample RMSE={r_tr:.4f} | OOF RMSE={r_oof:.4f} | Test RMSE={r_te:.4f}\")\n\nprint(\"\\n=== Bencana In-Sample Stacking vs Strict Out-of-Fold (OOF) Stacking ===\")\nw_leak = meta_leaky.coef_\nw_oof = meta_oof.coef_\nprint(f\"In-Sample (BOCOR) | Bobot [Ridge, GBDT, OverfitTree] = [{w_leak[0]:+.4f}, {w_leak[1]:+.4f}, {w_leak[2]:+.4f}] | Test RMSE={root_mean_squared_error(y_te, pred_leaky):.4f}\")\nprint(f\"Strict 5-Fold OOF | Bobot [Ridge, GBDT, OverfitTree] = [{w_oof[0]:+.4f}, {w_oof[1]:+.4f}, {w_oof[2]:+.4f}] | Test RMSE={root_mean_squared_error(y_te, pred_oof):.4f}\")",
