          "filename": "18_2_sklearn_stacking_classifier_regressor.py",
          "code": "import numpy as np\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import (\n    ExtraTreesClassifier,\n    ExtraTreesRegressor,\n    GradientBoostingRegressor,\n    HistGradientBoostingClassifier,\n    StackingClassifier,\n    StackingRegressor,\n)\nfrom sklearn.linear_model import LogisticRegression, Ridge, RidgeCV\nfrom sklearn.metrics import log_loss, roc_auc_score, root_mean_squared_error\nfrom sklearn.model_selection import StratifiedKFold, train_test_split\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import SplineTransformer, StandardScaler\n\n# 1) Klasifikasi Biner: StackingClassifier(cv=StratifiedKFold(5), final_estimator=LogisticRegression)\nXc, yc = make_classification(\n    n_samples=750, n_features=12, n_informative=7, n_redundant=2,\n    class_sep=0.90, flip_y=0.04, random_state=42\n)\nXc_tr, Xc_te, yc_tr, yc_te = train_test_split(Xc, yc, test_size=0.30, stratify=yc, random_state=42)\n\nbase_cls = [\n    (\"logreg\", Pipeline([(\"sc\", StandardScaler()), (\"m\", LogisticRegression(C=0.6, random_state=42))])),\n    (\"mlp\", Pipeline([(\"sc\", StandardScaler()), (\"m\", MLPClassifier(hidden_layer_sizes=(20, 10), solver=\"lbfgs\", alpha=0.5, max_iter=100, random_state=42))])),\n    (\"et\", ExtraTreesClassifier(n_estimators=28, min_samples_leaf=3, random_state=42)),\n    (\"hgb\", HistGradientBoostingClassifier(max_iter=28, max_depth=4, max_bins=48, early_stopping=False, random_state=42)),\n]\n\nstack_cls = StackingClassifier(\n    estimators=base_cls,\n    final_estimator=LogisticRegression(C=0.5, random_state=42),\n    cv=StratifiedKFold(n_splits=5, shuffle=True, random_state=42),\n    stack_method=\"predict_proba\",\n    passthrough=False,\n    n_jobs=1,\n).fit(Xc_tr, yc_tr)\n\nprint(\"=== 1. StackingClassifier (5-Fold Stratified OOF, Meta=LogisticRegression(C=0.5)) ===\")\nfor (name, _), fitted_est in zip(base_cls, stack_cls.estimators_):\n    p = fitted_est.predict_proba(Xc_te)[:, 1]\n    print(f\"  Base {name:8s} | Test AUROC={roc_auc_score(yc_te, p):.4f} | Test LogLoss={log_loss(yc_te, p):.4f}\")\np_st = stack_cls.predict_proba(Xc_te)[:, 1]\ncoefs_c = stack_cls.final_estimator_.coef_[0]\nprint(f\"  STACKING OOF  | Test AUROC={roc_auc_score(yc_te, p_st):.4f} | Test LogLoss={log_loss(yc_te, p_st):.4f}\")\nprint(\"  Koefisien Meta [logreg, mlp, et, hgb]:\", [round(float(c), 4) for c in coefs_c])\n\n# 2) Regresi: StackingRegressor dengan Meta-Learner RidgeCV Ber-Regularisasi\nrng = np.random.default_rng(42)\nXr = rng.uniform(-2.0, 2.0, size=(600, 5))\nyr = 2.0 * Xr[:, 0] + 1.5 * np.sin(1.8 * Xr[:, 1]) + 1.8 * (Xr[:, 2] > 0.2) * Xr[:, 3] + rng.normal(0.0, 0.7, size=600)\nXr_tr, Xr_te, yr_tr, yr_te = train_test_split(Xr, yr, test_size=0.30, random_state=42)\n\nbase_reg = [\n    (\"spline_ridge\", Pipeline([(\"sp\", SplineTransformer(n_knots=5, degree=3)), (\"rg\", Ridge(alpha=1.5))])),\n    (\"et_reg\", ExtraTreesRegressor(n_estimators=28, min_samples_leaf=3, random_state=42)),\n    (\"gbdt_reg\", GradientBoostingRegressor(n_estimators=32, max_depth=3, learning_rate=0.09, random_state=42)),\n]\nstack_reg = StackingRegressor(\n    estimators=base_reg,\n    final_estimator=RidgeCV(alphas=np.logspace(-2, 3, 25)),\n    cv=5,\n    n_jobs=1,\n).fit(Xr_tr, yr_tr)\n\nprint(\"\\n=== 2. StackingRegressor (5-Fold OOF, Meta=RidgeCV) ===\")\nfor (name, _), fitted_est in zip(base_reg, stack_reg.estimators_):\n    print(f\"  Base {name:12s} | Test RMSE={root_mean_squared_error(yr_te, fitted_est.predict(Xr_te)):.4f}\")\npred_sr = stack_reg.predict(Xr_te)\nprint(f\"  STACKING OOF      | Test RMSE={root_mean_squared_error(yr_te, pred_sr):.4f} | RidgeCV alpha*={stack_reg.final_estimator_.alpha_:.3f}\")\nprint(\"  Bobot Meta [spline_ridge, et_reg, gbdt_reg]:\", [round(float(c), 4) for c in stack_reg.final_estimator_.coef_])",
          "expectedOutput": "=== 1. StackingClassifier (5-Fold Stratified OOF, Meta=LogisticRegression(C=0.5)) ===\n  Base logreg   | Test AUROC=0.8759 | Test LogLoss=0.4588\n  Base mlp      | Test AUROC=0.9061 | Test LogLoss=0.8235\n  Base et       | Test AUROC=0.9149 | Test LogLoss=0.4527\n  Base hgb      | Test AUROC=0.8960 | Test LogLoss=0.4360\n  STACKING OOF  | Test AUROC=0.9294 | Test LogLoss=0.3519\n  Koefisien Meta [logreg, mlp, et, hgb]: [0.7181, 1.9424, 2.3729, 1.6996]\n\n=== 2. StackingRegressor (5-Fold OOF, Meta=RidgeCV) ===\n  Base spline_ridge | Test RMSE=1.2950\n  Base et_reg       | Test RMSE=1.2163\n  Base gbdt_reg     | Test RMSE=1.1900\n  STACKING OOF      | Test RMSE=1.0917 | RidgeCV alpha*=34.807\n  Bobot Meta [spline_ridge, et_reg, gbdt_reg]: [0.2888, 0.3422, 0.4994]",
