          "filename": "18_2_stacking_collinearity_group_leakage_audit.py",
          "code": "import numpy as np\nfrom scipy.optimize import nnls\nfrom sklearn.ensemble import GradientBoostingRegressor, RandomForestClassifier\nfrom sklearn.linear_model import LinearRegression, LogisticRegression, RidgeCV\nfrom sklearn.metrics import roc_auc_score, root_mean_squared_error\nfrom sklearn.model_selection import KFold, StratifiedGroupKFold, StratifiedKFold, cross_val_predict\n\nrng = np.random.default_rng(1823)\n\n# AUDIT 1: Kolinearitas Matriks Z_oof -> Instabilitas OLS vs RidgeCV vs NNLS\nn_tr, n_te = 400, 260\nX = rng.normal(0.0, 1.0, size=(n_tr + n_te, 6))\ny = 2.2 * X[:, 0] - 1.5 * X[:, 1] + 1.1 * (X[:, 2] ** 2) + rng.normal(0.0, 1.0, size=n_tr + n_te)\nX_tr, y_tr, X_te, y_te = X[:n_tr], y[:n_tr], X[n_tr:], y[n_tr:]\n\n# 4 GBDT sangat berkorelasi -> matriks OOF ill-conditioned!\nspecs = [\n    GradientBoostingRegressor(n_estimators=40, max_depth=3, learning_rate=lr, subsample=0.92, random_state=10 + i)\n    for i, lr in enumerate([0.07, 0.08, 0.09, 0.10])\n]\nkf = KFold(n_splits=5, shuffle=True, random_state=42)\nZ_oof = np.column_stack([cross_val_predict(m, X_tr, y_tr, cv=kf) for m in specs])\nZ_te = np.column_stack([m.fit(X_tr, y_tr).predict(X_te) for m in specs])\ncond_num = float(np.linalg.cond(Z_oof.T @ Z_oof))\n\nols = LinearRegression().fit(Z_oof, y_tr)\nrdg = RidgeCV(alphas=np.logspace(-1, 3, 25)).fit(Z_oof, y_tr)\nw_nnls, _ = nnls(Z_oof, y_tr)\nw_nnls_norm = w_nnls / max(float(np.sum(w_nnls)), 1e-12)\n\nprint(\"=== 1. Audit Kolinearitas Matriks Z_oof (4 Model Berkorelasi Tinggi) ===\")\nprint(f\"Condition Number cond(Z_oof^T Z_oof) = {cond_num:,.1f} (ekstrem ill-conditioned!)\")\nprint(f\"  OLS (Tanpa Regularisasi) | coef={np.round(ols.coef_, 3).tolist()} | Test RMSE={root_mean_squared_error(y_te, ols.predict(Z_te)):.4f}\")\nprint(f\"  RidgeCV (L2 Optimal)     | coef={np.round(rdg.coef_, 3).tolist()} | Test RMSE={root_mean_squared_error(y_te, rdg.predict(Z_te)):.4f}\")\nprint(f\"  NNLS (Non-Negatif)       | coef={np.round(w_nnls_norm, 3).tolist()} | Test RMSE={root_mean_squared_error(y_te, Z_te @ w_nnls_norm):.4f}\")\n\n# AUDIT 2: Kebocoran Entitas pada OOF Stacking (Random KFold vs StratifiedGroupKFold)\n# Setiap merchant memiliki profil statis 4 fitur (fingerprint) + efek laten spesifik-merchant tak teramati\nn_merch = 180\ntx_per_merch = 6\nn_tot = n_merch * tx_per_merch\nmerch_ids = np.repeat(np.arange(n_merch), tx_per_merch)\nmerch_profile = rng.normal(0.0, 1.5, size=(n_merch, 4))\nmerch_latent_idiosync = rng.normal(0.0, 2.2, size=n_merch)  # efek unik per merchant (bisa dihafal lewat fingerprint!)\nX_tx = merch_profile[merch_ids] + rng.normal(0.0, 0.05, size=(n_tot, 4))\ntx_feat = rng.normal(0.0, 1.0, size=(n_tot, 2))\nX_panel = np.hstack([X_tx, tx_feat])\nlogits_p = 0.7 * merch_profile[merch_ids, 0] + merch_latent_idiosync[merch_ids] + 0.8 * tx_feat[:, 0] - 0.5\ny_panel = (rng.uniform(0, 1, size=n_tot) < 1.0 / (1.0 + np.exp(-logits_p))).astype(int)\n\n# Pisah 125 merchant untuk train OOF, 55 merchant BARU untuk true unseen test\ntr_mask = merch_ids < 125\nXp_tr, yp_tr, gp_tr = X_panel[tr_mask], y_panel[tr_mask], merch_ids[tr_mask]\nXp_te, yp_te = X_panel[~tr_mask], y_panel[~tr_mask]\n\nbase_a = RandomForestClassifier(n_estimators=45, min_samples_leaf=1, random_state=42)\nbase_b = LogisticRegression(C=0.5, random_state=42)\n\n# OOF Bocor: StratifiedKFold acak memecah transaksi merchant yang sama ke train & val\nskf = StratifiedKFold(n_splits=5, shuffle=True, random_state=42)\noof_leak = np.column_stack([\n    cross_val_predict(base_a, Xp_tr, yp_tr, cv=skf, method=\"predict_proba\")[:, 1],\n    cross_val_predict(base_b, Xp_tr, yp_tr, cv=skf, method=\"predict_proba\")[:, 1],\n])\n# OOF Jujur: StratifiedGroupKFold mengunci seluruh transaksi 1 merchant di fold yang sama\nsgkf = StratifiedGroupKFold(n_splits=5)\noof_safe = np.column_stack([\n    cross_val_predict(base_a, Xp_tr, yp_tr, groups=gp_tr, cv=sgkf, method=\"predict_proba\")[:, 1],\n    cross_val_predict(base_b, Xp_tr, yp_tr, groups=gp_tr, cv=sgkf, method=\"predict_proba\")[:, 1],\n])\n\nmeta_l = LogisticRegression(C=1.0).fit(oof_leak, yp_tr)\nmeta_s = LogisticRegression(C=1.0).fit(oof_safe, yp_tr)\nZ_panel_te = np.column_stack([\n    base_a.fit(Xp_tr, yp_tr).predict_proba(Xp_te)[:, 1],\n    base_b.fit(Xp_tr, yp_tr).predict_proba(Xp_te)[:, 1],\n])\n\nprint(\"\\n=== 2. Audit Kebocoran Entitas OOF pada Data Panel Merchant (6 tx/merchant) ===\")\nprint(f\"OOF StratifiedKFold (BOCOR)   | OOF AUC={roc_auc_score(yp_tr, meta_l.predict_proba(oof_leak)[:,1]):.4f} | Unseen Merchant Test AUC={roc_auc_score(yp_te, meta_l.predict_proba(Z_panel_te)[:,1]):.4f} | Meta Coef={np.round(meta_l.coef_[0], 3).tolist()}\")\nprint(f\"OOF StratifiedGroupKFold(AMAN)| OOF AUC={roc_auc_score(yp_tr, meta_s.predict_proba(oof_safe)[:,1]):.4f} | Unseen Merchant Test AUC={roc_auc_score(yp_te, meta_s.predict_proba(Z_panel_te)[:,1]):.4f} | Meta Coef={np.round(meta_s.coef_[0], 3).tolist()}\")",
          "expectedOutput": "=== 1. Audit Kolinearitas Matriks Z_oof (4 Model Berkorelasi Tinggi) ===\nCondition Number cond(Z_oof^T Z_oof) = 738.8 (ekstrem ill-conditioned!)\n  OLS (Tanpa Regularisasi) | coef=[-0.896, -0.023, 0.691, 1.317] | Test RMSE=1.3731\n  RidgeCV (L2 Optimal)     | coef=[-0.737, 0.035, 0.6, 1.207] | Test RMSE=1.3702\n  NNLS (Non-Negatif)       | coef=[0.0, 0.0, 0.025, 0.975] | Test RMSE=1.3759\n\n=== 2. Audit Kebocoran Entitas OOF pada Data Panel Merchant (6 tx/merchant) ===\nOOF StratifiedKFold (BOCOR)   | OOF AUC=0.7673 | Unseen Merchant Test AUC=0.6298 | Meta Coef=[3.951, 0.829]\nOOF StratifiedGroupKFold(AMAN)| OOF AUC=0.6355 | Unseen Merchant Test AUC=0.6842 | Meta Coef=[-0.601, 2.473]",
