          "code": "import numpy as np\nfrom scipy.stats import rankdata\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\n\nrng = np.random.default_rng(183)\nn = 1400\n\n# Simulasikan data kelas timpang (prevalensi ~8.5%) + 4 model dengan skala kalibrasi berbeda\nz_true = rng.normal(-2.75, 1.35, size=n)\np_true = 1.0 / (1.0 + np.exp(-z_true))\ny = (rng.uniform(0.0, 1.0, size=n) < p_true).astype(int)\n\n# 4 model kandidat: (1) terkalibrasi, (2) over-confident tajam, (3) under-confident datar, (4) beragam kuat\np1 = 1.0 / (1.0 + np.exp(-(z_true + rng.normal(0.0, 0.70, size=n))))\np2 = 1.0 / (1.0 + np.exp(-(1.65 * z_true + rng.normal(0.0, 0.85, size=n))))  # over-confident\np3 = 1.0 / (1.0 + np.exp(-(0.55 * z_true + 0.65 + rng.normal(0.0, 0.55, size=n))))  # under-confident + bias shift\np4 = 1.0 / (1.0 + np.exp(-(0.95 * z_true + rng.normal(0.0, 0.62, size=n))))\nP = np.vstack([p1, p2, p3, p4])  # (M, n)\n\ndef logit(p: np.ndarray) -> np.ndarray:\n    pc = np.clip(p, 1e-6, 1.0 - 1e-6)\n    return np.log(pc / (1.0 - pc))\n\ndef sigmoid(z: np.ndarray) -> np.ndarray:\n    return 1.0 / (1.0 + np.exp(-np.clip(z, -30.0, 30.0)))\n\ndef compute_ece(y_t: np.ndarray, p_hat: np.ndarray, n_bins: int = 10) -> float:\n    edges = np.linspace(0.0, 1.0, n_bins + 1)\n    ece = 0.0\n    for b in range(n_bins):\n        mask = (p_hat >= edges[b]) & (p_hat < edges[b + 1] if b < n_bins - 1 else p_hat <= edges[b + 1])\n        if np.any(mask):\n            ece += float(np.mean(mask)) * abs(float(np.mean(p_hat[mask])) - float(np.mean(y_t[mask])))\n    return ece\n\n# 4 Operator Penggabungan Probabilitas (bobot seragam untuk isolasi efek operator)\np_linear = np.mean(P, axis=0)\np_geom = np.exp(np.mean(np.log(np.clip(P, 1e-6, 1.0)), axis=0))\np_logodds = sigmoid(np.mean(logit(P), axis=0))\np_rank = np.mean(np.vstack([rankdata(P[m]) / n for m in range(P.shape[0])]), axis=0)\n\n# Algoritma Caruana Forward Stepwise Ensemble Selection WITH REPLACEMENT (2004 / AutoGluon / TabArena 2025)\ndef caruana_ensemble_selection(P_mat: np.ndarray, y_t: np.ndarray, n_steps: int = 25, metric: str = \"log_loss\"):\n    M = P_mat.shape[0]\n    counts = np.zeros(M, dtype=int)\n    running_sum = np.zeros_like(P_mat[0])\n    for step in range(1, n_steps + 1):\n        best_m = 0\n        best_score = np.inf if metric == \"log_loss\" else -np.inf\n        for m in range(M):\n            cand = (running_sum + P_mat[m]) / step\n            if metric == \"log_loss\":\n                sc = float(log_loss(y_t, np.clip(cand, 1e-6, 1.0 - 1e-6)))\n                if sc < best_score:\n                    best_score, best_m = sc, m\n            else:\n                sc = float(roc_auc_score(y_t, cand))\n                if sc > best_score:\n                    best_score, best_m = sc, m\n        running_sum += P_mat[best_m]\n        counts[best_m] += 1\n    weights = counts / float(n_steps)\n    return weights, weights @ P_mat\n\nw_car_ll, p_car_ll = caruana_ensemble_selection(P, y, n_steps=25, metric=\"log_loss\")\nw_car_auc, p_car_auc = caruana_ensemble_selection(P, y, n_steps=25, metric=\"roc_auc\")\n\nprint(f\"=== Perbandingan Operator Agregasi & Caruana Selection (Prevalensi Nyata={y.mean():.4f}) ===\")\nprint(\"Metode Agregasi             | AUROC  | LogLoss | Brier  |  ECE   | Mean(p_hat)\")\nprint(\"-\" * 78)\nfor name, p_est in [\n    (\"Best Single (Model 4)\", p4),\n    (\"Linear Prob Averaging\", p_linear),\n    (\"Geometric Mean Pooling\", p_geom),\n    (\"Log-Odds (Logit) Pooling\", p_logodds),\n    (\"Rank Averaging (MERUSAK!)\", p_rank),\n    (\"Caruana Selection (LogLoss)\", p_car_ll),\n    (\"Caruana Selection (AUROC)\", p_car_auc),\n]:\n    pc = np.clip(p_est, 1e-6, 1.0 - 1e-6)\n    print(f\"{name:27s} | {roc_auc_score(y, pc):.4f} | {log_loss(y, pc):7.4f} | {brier_score_loss(y, pc):.4f} | {compute_ece(y, pc):.4f} | {pc.mean():.4f}\")\n\nprint(\"Bobot Caruana (LogLoss) [m1..m4]:\", np.round(w_car_ll, 2).tolist())\nprint(\"Bobot Caruana (AUROC)   [m1..m4]:\", np.round(w_car_auc, 2).tolist())",
          "expectedOutput": "=== Perbandingan Operator Agregasi & Caruana Selection (Prevalensi Nyata=0.0979) ===\nMetode Agregasi             | AUROC  | LogLoss | Brier  |  ECE   | Mean(p_hat)\n------------------------------------------------------------------------------\nBest Single (Model 4)       | 0.7790 |  0.2773 | 0.0800 | 0.0292 | 0.1257\nLinear Prob Averaging       | 0.7916 |  0.2852 | 0.0805 | 0.0640 | 0.1601\nGeometric Mean Pooling      | 0.7948 |  0.2662 | 0.0767 | 0.0168 | 0.1128\nLog-Odds (Logit) Pooling    | 0.7958 |  0.2679 | 0.0775 | 0.0244 | 0.1205\nRank Averaging (MERUSAK!)   | 0.7942 |  0.7726 | 0.2709 | 0.4025 | 0.5004\nCaruana Selection (LogLoss) | 0.7948 |  0.2648 | 0.0758 | 0.0137 | 0.1023\nCaruana Selection (AUROC)   | 0.7960 |  0.2686 | 0.0766 | 0.0299 | 0.1256\nBobot Caruana (LogLoss) [m1..m4]: [0.16, 0.52, 0.04, 0.28]\nBobot Caruana (AUROC)   [m1..m4]: [0.12, 0.4, 0.12, 0.36]",
