          "code": "import numpy as np\nfrom scipy.optimize import minimize\nfrom scipy.stats import rankdata\nfrom sklearn.datasets import make_classification\nfrom sklearn.ensemble import ExtraTreesClassifier, HistGradientBoostingClassifier, RandomForestClassifier\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import brier_score_loss, log_loss, roc_auc_score\nfrom sklearn.model_selection import StratifiedKFold, train_test_split\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import SplineTransformer, StandardScaler\n\nX, y = make_classification(\n    n_samples=800, n_features=12, n_informative=7, n_redundant=2,\n    weights=[0.88, 0.12], class_sep=0.95, flip_y=0.03, random_state=183\n)\nX_dev, X_lock, y_dev, y_lock = train_test_split(X, y, test_size=0.25, stratify=y, random_state=42)\n\ndef make_zoo():\n    return [\n        (\"LogReg\", Pipeline([(\"sc\", StandardScaler()), (\"m\", LogisticRegression(C=0.6, random_state=42))])),\n        (\"SplineLog\", Pipeline([(\"sp\", SplineTransformer(n_knots=4, degree=2)), (\"m\", LogisticRegression(C=0.4, max_iter=200, random_state=42))])),\n        (\"RF\", RandomForestClassifier(n_estimators=24, min_samples_leaf=4, random_state=42)),\n        (\"ExtraTrees\", ExtraTreesClassifier(n_estimators=24, min_samples_leaf=3, random_state=42)),\n        (\"HGB_d3\", HistGradientBoostingClassifier(max_iter=24, max_depth=3, max_bins=32, learning_rate=0.10, early_stopping=False, random_state=42)),\n        (\"HGB_d6\", HistGradientBoostingClassifier(max_iter=24, max_depth=6, max_bins=32, l2_regularization=2.0, learning_rate=0.10, early_stopping=False, random_state=43)),\n        (\"MLP\", Pipeline([(\"sc\", StandardScaler()), (\"m\", MLPClassifier(hidden_layer_sizes=(16,), solver=\"lbfgs\", alpha=1.2, max_iter=80, random_state=42))])),\n    ]\n\n# 1) Bangun OOF 3-Fold Ketat untuk 7 Kandidat + Refit Penuh untuk Lockbox Test\nskf = StratifiedKFold(n_splits=3, shuffle=True, random_state=42)\nnames = [n for n, _ in make_zoo()]\nM = len(names)\nOOF = np.zeros((M, len(y_dev)))\nLOCK = np.zeros((M, len(y_lock)))\n\nfor tr_i, va_i in skf.split(X_dev, y_dev):\n    for m, (_, mdl) in enumerate(make_zoo()):\n        mdl.fit(X_dev[tr_i], y_dev[tr_i])\n        OOF[m, va_i] = mdl.predict_proba(X_dev[va_i])[:, 1]\n\nfor m, (_, mdl) in enumerate(make_zoo()):\n    mdl.fit(X_dev, y_dev)\n    LOCK[m] = mdl.predict_proba(X_lock)[:, 1]\n\n# 2) Holdout Blending (Sisihkan 15% dari X_dev khusus untuk fitting bobot convex)\nXb_tr, Xb_val, yb_tr, yb_val = train_test_split(X_dev, y_dev, test_size=0.15, stratify=y_dev, random_state=7)\nB_val = np.zeros((M, len(yb_val)))\nB_lock = np.zeros((M, len(y_lock)))\nfor m, (_, mdl) in enumerate(make_zoo()):\n    mdl.fit(Xb_tr, yb_tr)\n    B_val[m] = mdl.predict_proba(Xb_val)[:, 1]\n    B_lock[m] = mdl.predict_proba(X_lock)[:, 1]\n\nres_blend = minimize(\n    lambda w: log_loss(yb_val, np.clip(w @ B_val, 1e-6, 1 - 1e-6)),\n    x0=np.full(M, 1.0 / M),\n    bounds=[(0.0, 1.0)] * M,\n    constraints={\"type\": \"eq\", \"fun\": lambda w: np.sum(w) - 1.0},\n)\np_blend_lock = res_blend.x @ B_lock\n\n# 3) Caruana Forward Stepwise Selection (AutoGluon / TabArena 2025 pattern) pada OOF Log-Loss\ncounts = np.zeros(M, dtype=int)\nrsum = np.zeros(len(y_dev))\nT_steps = 25\nfor t in range(1, T_steps + 1):\n    losses = [log_loss(y_dev, np.clip((rsum + OOF[m]) / t, 1e-6, 1 - 1e-6)) for m in range(M)]\n    best_m = int(np.argmin(losses))\n    rsum += OOF[best_m]\n    counts[best_m] += 1\nw_caruana = counts / float(T_steps)\n\n# 4) Operator pembanding di Lockbox\ndef logit(p):\n    pc = np.clip(p, 1e-6, 1 - 1e-6)\n    return np.log(pc / (1 - pc))\n\ndef sigmoid(z):\n    return 1.0 / (1.0 + np.exp(-np.clip(z, -30.0, 30.0)))\n\nbest_single_idx = int(np.argmin([log_loss(y_dev, np.clip(OOF[m], 1e-6, 1 - 1e-6)) for m in range(M)]))\np_eq_lin = np.mean(LOCK, axis=0)\np_eq_logodds = sigmoid(np.mean(logit(LOCK), axis=0))\np_rank_lock = np.mean(np.vstack([rankdata(LOCK[m]) / len(y_lock) for m in range(M)]), axis=0)\np_car_lock = w_caruana @ LOCK\np_car_logodds = sigmoid(w_caruana @ logit(LOCK))\n\nprint(f\"=== Benchmark 7-Model Library pada Lockbox Test (N={len(y_lock)}, BaseRate={y_lock.mean():.3f}) ===\")\nprint(\"Strategi Ensemble                | Lock AUROC | Lock LogLoss | Lock Brier | Mean(p)\")\nprint(\"-\" * 82)\nfor label, p_l in [\n    (f\"Best Single ({names[best_single_idx]})\", LOCK[best_single_idx]),\n    (\"Holdout Blending (15% split)\", p_blend_lock),\n    (\"OOF Equal Linear Avg\", p_eq_lin),\n    (\"OOF Equal Log-Odds Pool\", p_eq_logodds),\n    (\"OOF Rank Averaging\", p_rank_lock),\n    (\"OOF Caruana Selection (Lin)\", p_car_lock),\n    (\"OOF Caruana Selection (LogOdds)\", p_car_logodds),\n]:\n    pc = np.clip(p_l, 1e-6, 1 - 1e-6)\n    print(f\"{label:32s} | {roc_auc_score(y_lock, pc):10.4f} | {log_loss(y_lock, pc):12.4f} | {brier_score_loss(y_lock, pc):10.4f} | {pc.mean():7.4f}\")\n\nselected = {names[m]: round(float(w_caruana[m]), 2) for m in range(M) if w_caruana[m] > 0}\nprint(\"Bobot Caruana Terpilih (AutoGluon-style):\", selected)",
          "expectedOutput": "=== Benchmark 7-Model Library pada Lockbox Test (N=200, BaseRate=0.135) ===\nStrategi Ensemble                | Lock AUROC | Lock LogLoss | Lock Brier | Mean(p)\n----------------------------------------------------------------------------------\nBest Single (HGB_d3)             |     0.8453 |       0.2853 |     0.0833 |  0.1257\nHoldout Blending (15% split)     |     0.8255 |       0.2666 |     0.0708 |  0.1313\nOOF Equal Linear Avg             |     0.8334 |       0.2884 |     0.0834 |  0.1293\nOOF Equal Log-Odds Pool          |     0.8446 |       0.2819 |     0.0823 |  0.1177\nOOF Rank Averaging               |     0.8331 |       0.6888 |     0.2371 |  0.5025\nOOF Caruana Selection (Lin)      |     0.8292 |       0.2856 |     0.0824 |  0.1282\nOOF Caruana Selection (LogOdds)  |     0.8411 |       0.2861 |     0.0829 |  0.1181\nBobot Caruana Terpilih (AutoGluon-style): {'LogReg': 0.04, 'SplineLog': 0.16, 'RF': 0.08, 'ExtraTrees': 0.08, 'HGB_d3': 0.08, 'MLP': 0.56}",
          "actualOutput": "=== Benchmark 7-Model Library pada Lockbox Test (N=200, BaseRate=0.135) ===\nStrategi Ensemble                | Lock AUROC | Lock LogLoss | Lock Brier | Mean(p)\n----------------------------------------------------------------------------------\nBest Single (HGB_d3)             |     0.8453 |       0.2853 |     0.0833 |  0.1257\nHoldout Blending (15% split)     |     0.8255 |       0.2666 |     0.0708 |  0.1313\nOOF Equal Linear Avg             |     0.8334 |       0.2884 |     0.0834 |  0.1293\nOOF Equal Log-Odds Pool          |     0.8446 |       0.2819 |     0.0823 |  0.1177\nOOF Rank Averaging               |     0.8331 |       0.6888 |     0.2371 |  0.5025\nOOF Caruana Selection (Lin)      |     0.8292 |       0.2856 |     0.0824 |  0.1282\nOOF Caruana Selection (LogOdds)  |     0.8411 |       0.2861 |     0.0829 |  0.1181\nBobot Caruana Terpilih (AutoGluon-style): {'LogReg': 0.04, 'SplineLog': 0.16, 'RF': 0.08, 'ExtraTrees': 0.08, 'HGB_d3': 0.08, 'MLP': 0.56}",
