          "id": "code-ml-18-4-ch18_4_sklearn",
          "title": "Scikit-Learn 1.9: Knowledge Distillation 6-Model Teacher -> 1 Single HistGBDT Student",
          "language": "python",
          "filename": "18_4_sklearn_tabular_knowledge_distillation.py",
          "code": "import numpy as np\nfrom sklearn.ensemble import (\n    ExtraTreesClassifier,\n    HistGradientBoostingClassifier,\n    HistGradientBoostingRegressor,\n    RandomForestClassifier,\n)\nfrom sklearn.linear_model import LogisticRegression\nfrom sklearn.metrics import log_loss, roc_auc_score\nfrom sklearn.model_selection import train_test_split\nfrom sklearn.neural_network import MLPClassifier\nfrom sklearn.pipeline import Pipeline\nfrom sklearn.preprocessing import SplineTransformer, StandardScaler\n\nrng = np.random.default_rng(1842)\nN_tot = 4200\nX = rng.normal(0.0, 1.0, size=(N_tot, 8))\n# Pola kompleks campuran halus + interaksi non-linier + kuadratik\nz_true = (\n    1.6 * X[:, 0]\n    - 1.4 * np.sin(1.5 * X[:, 1])\n    + 1.5 * X[:, 2] * X[:, 3]\n    + 1.2 * ((X[:, 4] > 0.2) & (X[:, 5] < 0.3)).astype(float)\n    - 0.9 * (X[:, 6] ** 2)\n    + 0.6 * X[:, 7]\n    - 0.5\n)\np_true = 1.0 / (1.0 + np.exp(-z_true))\ny = (rng.uniform(0.0, 1.0, size=N_tot) < p_true).astype(int)\n\n# Split realistis produksi: 550 baris berlabel (latih), 3050 baris UNLABELED transfer set, 600 lockbox uji\nX_lab, X_rest, y_lab, y_rest = train_test_split(X, y, train_size=550, stratify=y, random_state=42)\nX_unlab, X_lock, _, y_lock = train_test_split(X_rest, y_rest, test_size=600, stratify=y_rest, random_state=42)\n\ndef to_logit(p: np.ndarray) -> np.ndarray:\n    pc = np.clip(p, 1e-5, 1.0 - 1e-5)\n    return np.log(pc / (1.0 - pc))\n\ndef sigmoid(z: np.ndarray) -> np.ndarray:\n    return 1.0 / (1.0 + np.exp(-np.clip(z, -30.0, 30.0)))\n\n# 1) Teacher Ensemble Berat (6 Model Heterogen ter-regularisasi baik — profil simulasi p99 ~27 ms -> GAGAL SLA 15ms!)\nteacher_models = [\n    (\"HGB_1\", HistGradientBoostingClassifier(max_iter=45, max_leaf_nodes=20, max_bins=64, l2_regularization=2.0, learning_rate=0.08, early_stopping=False, random_state=1)),\n    (\"HGB_2\", HistGradientBoostingClassifier(max_iter=45, max_depth=4, max_bins=64, l2_regularization=5.0, learning_rate=0.08, early_stopping=False, random_state=2)),\n    (\"RF\", RandomForestClassifier(n_estimators=40, min_samples_leaf=4, random_state=3)),\n    (\"ExtraTrees\", ExtraTreesClassifier(n_estimators=40, min_samples_leaf=4, random_state=4)),\n    (\"MLP\", Pipeline([(\"sc\", StandardScaler()), (\"m\", MLPClassifier(hidden_layer_sizes=(24, 12), solver=\"lbfgs\", alpha=4.0, max_iter=120, random_state=5))])),\n    (\"SplineLog\", Pipeline([(\"sp\", SplineTransformer(n_knots=4, degree=2)), (\"m\", LogisticRegression(C=0.4, max_iter=200, random_state=6))])),\n]\nfor _, mdl in teacher_models:\n    mdl.fit(X_lab, y_lab)\n\ndef teacher_soft_logit(X_in: np.ndarray) -> np.ndarray:\n    logits = np.vstack([np.clip(to_logit(mdl.predict_proba(X_in)[:, 1]), -5.5, 5.5) for _, mdl in teacher_models])\n    return np.mean(logits, axis=0)\n\np_teacher_lock = sigmoid(teacher_soft_logit(X_lock))\n\n# 2) Single Student Standar (Hard Labels 0/1 saja pada 550 baris berlabel, pohon ringan untuk SLA < 15ms)\nhard_student = HistGradientBoostingClassifier(\n    max_iter=25, max_leaf_nodes=10, max_bins=64, learning_rate=0.08, early_stopping=False, random_state=42\n).fit(X_lab, y_lab)\np_hard_lock = hard_student.predict_proba(X_lock)[:, 1]\n\n# 3) Pruned 2-Model Ensemble (HGB_1 + MLP ter-regularisasi — hemat tapi masih 2 runtime pipeline)\np_pruned_lock = sigmoid(0.5 * (\n    np.clip(to_logit(teacher_models[0][1].predict_proba(X_lock)[:, 1]), -5.5, 5.5)\n    + np.clip(to_logit(teacher_models[4][1].predict_proba(X_lock)[:, 1]), -5.5, 5.5)\n))\n\n# 4) DISTILLED SINGLE STUDENT (Hinton 2015 / Bucilua 2006): 1 HistGBDT ringan meniru soft logits Teacher\n#    pada gabungan data berlabel + 3050 transaksi tak berlabel (transfer set)\nX_transfer = np.vstack([X_lab, X_unlab])\nz_soft_transfer = teacher_soft_logit(X_transfer)\ndistilled_student = HistGradientBoostingRegressor(\n    max_iter=90, max_leaf_nodes=31, max_bins=128, learning_rate=0.08, l2_regularization=0.1, early_stopping=False, random_state=42\n).fit(X_transfer, z_soft_transfer)\np_distilled_lock = sigmoid(distilled_student.predict(X_lock))\n\n# Profil latensi p99 simulasi deterministik (Monte Carlo 20k request, seed tetap)\nr_lat = np.random.default_rng(77)\n# Parameter (median_ms, sigma_log) realistis produksi per keluarga\np99_teacher = float(np.percentile(np.max(np.column_stack([\n    r_lat.lognormal(np.log(3.2), 0.45, 20000),  # HGB_1\n    r_lat.lognormal(np.log(3.0), 0.45, 20000),  # HGB_2\n    r_lat.lognormal(np.log(6.8), 0.55, 20000),  # RF\n    r_lat.lognormal(np.log(6.2), 0.55, 20000),  # ET\n    r_lat.lognormal(np.log(4.8), 0.52, 20000),  # MLP\n    r_lat.lognormal(np.log(1.8), 0.35, 20000),  # Spline\n]), axis=1), 99))\np99_pruned = float(np.percentile(np.max(np.column_stack([\n    r_lat.lognormal(np.log(3.2), 0.45, 20000),\n    r_lat.lognormal(np.log(4.8), 0.52, 20000),\n]), axis=1), 99))\np99_student = float(np.percentile(r_lat.lognormal(np.log(2.4), 0.40, 20000), 99))\n\nauc_hard = roc_auc_score(y_lock, p_hard_lock)\nauc_teach = roc_auc_score(y_lock, p_teacher_lock)\nauc_prune = roc_auc_score(y_lock, p_pruned_lock)\nauc_dist = roc_auc_score(y_lock, p_distilled_lock)\ngain_ret = 100.0 * (auc_dist - auc_hard) / max(auc_teach - auc_hard, 1e-9)\n\nprint(f\"=== Benchmark Knowledge Distillation Tabular vs Teacher Ensemble (Lockbox N={len(y_lock)}) ===\")\nprint(\"Arsitektur Deployment         | Model | Lock AUROC | Lock LogLoss | Sim p99 | SLA<15ms\")\nprint(\"-\" * 88)\nrows = [\n    (\"Hard-Label Single HistGBDT\", 1, auc_hard, log_loss(y_lock, p_hard_lock), p99_student),\n    (\"Teacher Ensemble (6 Model)\", 6, auc_teach, log_loss(y_lock, p_teacher_lock), p99_teacher),\n    (\"Pruned 2-Model (HGB+MLP)\", 2, auc_prune, log_loss(y_lock, p_pruned_lock), p99_pruned),\n    (\"Distilled Single HistGBDT\", 1, auc_dist, log_loss(y_lock, p_distilled_lock), p99_student),\n]\nfor lbl, k_m, a, ll, p99 in rows:\n    ok = \"PASS\" if p99 < 15.0 else \"BREACH!\"\n    print(f\"{lbl:29s} | {k_m:5d} | {a:10.4f} | {ll:12.4f} | {p99:6.2f} | {ok}\")\nprint(f\"Retensi Kenaikan AUROC Teacher oleh Distilled Student = {gain_ret:.1f}% (dengan 1 model tunggal!)\")",
          "expectedOutput": "=== Benchmark Knowledge Distillation Tabular vs Teacher Ensemble (Lockbox N=600) ===\nArsitektur Deployment         | Model | Lock AUROC | Lock LogLoss | Sim p99 | SLA<15ms\n----------------------------------------------------------------------------------------\nHard-Label Single HistGBDT    |     1 |     0.7690 |       0.5498 |   6.15 | PASS\nTeacher Ensemble (6 Model)    |     6 |     0.8324 |       0.4922 |  27.04 | BREACH!\nPruned 2-Model (HGB+MLP)      |     2 |     0.8450 |       0.4672 |  16.54 | BREACH!\nDistilled Single HistGBDT     |     1 |     0.8171 |       0.5089 |   6.15 | PASS\nRetensi Kenaikan AUROC Teacher oleh Distilled Student = 75.9% (dengan 1 model tunggal!)",
          "actualOutput": "=== Benchmark Knowledge Distillation Tabular vs Teacher Ensemble (Lockbox N=600) ===\nArsitektur Deployment         | Model | Lock AUROC | Lock LogLoss | Sim p99 | SLA<15ms\n----------------------------------------------------------------------------------------\nHard-Label Single HistGBDT    |     1 |     0.7690 |       0.5498 |   6.15 | PASS\nTeacher Ensemble (6 Model)    |     6 |     0.8324 |       0.4922 |  27.04 | BREACH!\nPruned 2-Model (HGB+MLP)      |     2 |     0.8450 |       0.4672 |  16.54 | BREACH!\nDistilled Single HistGBDT     |     1 |     0.8171 |       0.5089 |   6.15 | PASS\nRetensi Kenaikan AUROC Teacher oleh Distilled Student = 75.9% (dengan 1 model tunggal!)",
