          "id": "code-ml-18-4-ch18_4_diag",
          "title": "Production Audit: Winner's Curse (Naive OOF vs Nested Lockbox) & Kurva Pareto Frontier p99",
          "language": "python",
          "filename": "18_4_nested_cv_winners_curse_pareto_audit.py",
          "code": "import numpy as np\nfrom sklearn.metrics import log_loss, roc_auc_score\n\nrng = np.random.default_rng(1843)\n\n# AUDIT 1: Winner's Curse / Meta-Overfitting saat Memilih Ensemble Tanpa Nested Outer Lockbox\n# 24 kandidat model yang semuanya memiliki kualitas intrinsik mirip + derau estimasi OOF\nn_inner, n_outer = 320, 600\nz_in = rng.normal(0.0, 1.25, size=n_inner)\ny_in = (rng.uniform(0, 1, size=n_inner) < 1.0 / (1.0 + np.exp(-z_in))).astype(int)\nz_out = rng.normal(0.0, 1.25, size=n_outer)\ny_out = (rng.uniform(0, 1, size=n_outer) < 1.0 / (1.0 + np.exp(-z_out))).astype(int)\n\nn_cands = 24\nP_in = np.vstack([1.0 / (1.0 + np.exp(-(0.75 * z_in + rng.normal(0.0, 1.15, size=n_inner)))) for _ in range(n_cands)])\nP_out = np.vstack([1.0 / (1.0 + np.exp(-(0.75 * z_out + rng.normal(0.0, 1.15, size=n_outer)))) for _ in range(n_cands)])\n\n# Jalankan Greedy Selection pada OOF tunggal (Inner) dan ukur bias optimisme di Outer Lockbox\ncounts = np.zeros(n_cands, dtype=int)\nrsum_in = np.zeros(n_inner)\nfor t in range(1, 21):\n    scores = [roc_auc_score(y_in, (rsum_in + P_in[m]) / t) for m in range(n_cands)]\n    bm = int(np.argmax(scores))\n    rsum_in += P_in[bm]\n    counts[bm] += 1\n\nw_sel = counts / 20.0\nauc_in_naive = roc_auc_score(y_in, w_sel @ P_in)\nauc_out_nested = roc_auc_score(y_out, w_sel @ P_out)\nll_in_naive = log_loss(y_in, np.clip(w_sel @ P_in, 1e-6, 1 - 1e-6))\nll_out_nested = log_loss(y_out, np.clip(w_sel @ P_out, 1e-6, 1 - 1e-6))\n\nprint(\"=== 1. Audit Winner's Curse: Evaluasi OOF Tunggal (Naive) vs Nested Outer Lockbox ===\")\nprint(f\"Skor OOF Tunggal (Optimis Palsu) | AUROC={auc_in_naive:.4f} | LogLoss={ll_in_naive:.4f}\")\nprint(f\"Skor Outer Nested Lockbox (Jujur)| AUROC={auc_out_nested:.4f} | LogLoss={ll_out_nested:.4f}\")\nprint(f\"Bias Optimisme Meta-Overfitting  | Delta AUROC={auc_in_naive - auc_out_nested:+.4f} | Delta LogLoss={ll_out_nested - ll_in_naive:+.4f}\")\n\n# AUDIT 2: Kurva Pareto Frontier Akurasi vs Tail Latency p99 (K=1..6 Model + Distilled Student)\n# Simulasi deterministik 15.000 permintaan untuk profil Pareto\nr_p = np.random.default_rng(303)\nn_sim = 15000\nprofiles = [\n    (\"K=1 (HGB Tunggal)\", [(2.8, 0.42)], 0.8580),\n    (\"K=2 (HGB + Spline)\", [(2.8, 0.42), (1.6, 0.34)], 0.8695),\n    (\"K=3 (+ MLP)\", [(2.8, 0.42), (1.6, 0.34), (4.6, 0.50)], 0.8768),\n    (\"K=4 (+ ExtraTrees)\", [(2.8, 0.42), (1.6, 0.34), (4.6, 0.50), (6.0, 0.54)], 0.8794),\n    (\"K=6 (+ RF + HGB2)\", [(2.8, 0.42), (1.6, 0.34), (4.6, 0.50), (6.0, 0.54), (6.8, 0.55), (3.1, 0.45)], 0.8812),\n    (\"Distilled Student (1x HGB)\", [(2.5, 0.40)], 0.8801),\n]\nprint(\"\\n=== 2. Pareto Frontier: Kenaikan AUROC vs Simulasi p99 Tail Latency (SLA <= 15.0 ms) ===\")\nprint(\"Konfigurasi                | AUROC  | Sim p99 | SLA Status | Gain/p99 (bps/ms)\")\nprint(\"-\" * 79)\nbase_auc = 0.8580\nfor name, specs, auc_v in profiles:\n    lats = np.column_stack([r_p.lognormal(np.log(med), sig, n_sim) for med, sig in specs])\n    p99 = float(np.percentile(np.max(lats, axis=1), 99))\n    status = \"SLA PASS\" if p99 <= 15.0 else \"SLA FAIL\"\n    gain_bps = (auc_v - base_auc) * 10000.0\n    print(f\"{name:26s} | {auc_v:.4f} | {p99:6.2f} | {status:10s} | {gain_bps / p99:17.2f}\")",
          "expectedOutput": "=== 1. Audit Winner's Curse: Evaluasi OOF Tunggal (Naive) vs Nested Outer Lockbox ===\nSkor OOF Tunggal (Optimis Palsu) | AUROC=0.8004 | LogLoss=0.5682\nSkor Outer Nested Lockbox (Jujur)| AUROC=0.7313 | LogLoss=0.6094\nBias Optimisme Meta-Overfitting  | Delta AUROC=+0.0691 | Delta LogLoss=+0.0412\n\n=== 2. Pareto Frontier: Kenaikan AUROC vs Simulasi p99 Tail Latency (SLA <= 15.0 ms) ===\nKonfigurasi                | AUROC  | Sim p99 | SLA Status | Gain/p99 (bps/ms)\n-------------------------------------------------------------------------------\nK=1 (HGB Tunggal)          | 0.8580 |   7.41 | SLA PASS   |              0.00\nK=2 (HGB + Spline)         | 0.8695 |   7.37 | SLA PASS   |             15.60\nK=3 (+ MLP)                | 0.8768 |  14.30 | SLA PASS   |             13.15\nK=4 (+ ExtraTrees)         | 0.8794 |  21.71 | SLA FAIL   |              9.86\nK=6 (+ RF + HGB2)          | 0.8812 |  26.10 | SLA FAIL   |              8.89\nDistilled Student (1x HGB) | 0.8801 |   6.35 | SLA PASS   |             34.81",
